const CACHE='poppy-v11';
const ASSETS=["./","./animation/blocks.js","./animation/curves.js","./animation/evaluate.js","./animation/sequence.js","./animation/timing.js","./app.js","./audio/audio.js","./audio/clips.js","./document/model.js","./document/validate.js","./export/codecs.js","./export/exporter.js","./export/png.js","./export/render.js","./index.html","./input/stage.js","./persistence/store.js","./persistence/svg-import.js","./phase-shapes.css","./properties-tabs.css","./reference/puppet.js","./renderer/svg.js","./scene/bevel.js","./scene/boolean.js","./scene/contour.js","./scene/matrix.js","./scene/mesh-edit.js","./scene/mesh-overlay.js","./scene/mesh-region.js","./scene/mesh.js","./scene/operations.js","./scene/shadow.js","./scene/shapes.js","./scene/strokes.js","./scene/svg-path.js","./scene/texture.js","./sequencer.css","./styles.css","./timeline/graph.js","./timeline/timeline.js","./track-editor.css","./ui/block-range.js","./ui/context.js","./ui/demo.js","./ui/editor.js","./ui/help.js","./ui/layer-menu.js","./ui/mesh-colour.js","./ui/properties.js","./ui/puppet.js","./ui/sequence.js","./ui/shapes-menu.js","./ui/texture.js","./ui/workspace.js","./vendor/mp4-muxer.js","./vendor/polygon-clipping.js","./vendor/webm-muxer.js","./workspace-controls.css"];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS.map(url=>new Request(new URL(url,self.location).href,{cache:'reload'})))).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request,{cache:'no-cache'}).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(event.request,copy));}return r;}).catch(()=>caches.match(event.request,{ignoreSearch:true})));});
